            var financialReads=new TreeMap<String,Object>();var marketReads=new TreeMap<String,Object>();var audited=overlay(ctx.getBean(HistoricalBacktestSeedMapper.class),prices,financial,financialReads);var builder=ctx.getBean(HistoricalBacktestSeedService.class);var build=HistoricalBacktestSeedService.class.getDeclaredMethod("buildSnapshot",HistoricalBacktestSeedMapper.class,String.class,LocalDate.class);build.setAccessible(true);
            var training=new ArrayList<StockBacktestResult>();var signalsByDay=new TreeMap<LocalDate,List<StockSignalSnapshot>>();var rowsByDay=new TreeMap<LocalDate,List<StockBacktestResult>>();var marketsByDay=new TreeMap<LocalDate,List<StockMarketSnapshot>>();var allDays=new ArrayList<>(TRAIN);allDays.addAll(TEST);
            for(var day:allDays){require(sha(protocol).equals(args[1]),"Protocol changed");var holding=holdingDates(calendar,day);var signals=new ArrayList<StockSignalSnapshot>();var markets=new ArrayList<StockMarketSnapshot>();for(String symbol:population){var signal=(StockSignalSnapshot)build.invoke(builder,audited,symbol,day);require(signal!=null,"Missing rebuilt10factor signal "+symbol+day);signals.add(signal);markets.add(market(db,symbol,day,prices.get(symbol).get(day).getClosePrice(),input.path("sharesBySymbol").path(symbol),marketReads));}rank(signals);var rows=new ArrayList<StockBacktestResult>();Double b=CompleteBenchmarkReturn.compound(benchmark,RESEARCH,holding.getFirst(),holding.getLast(),20);require(b!=null,"Incomplete20D benchmark "+day);for(var signal:signals){String symbol=signal.getSymbol();var bars=prices.get(symbol).subMap(holding.getFirst(),true,holding.getLast(),true).values().stream().toList();require(bars.size()==21&&bars.stream().map(StockCandleDaily::getTradeDate).toList().equals(holding)&&bars.stream().allMatch(c->c.getClosePrice()!=null&&c.getClosePrice().signum()>0),"Incomplete21positive closes "+symbol+day);var m=markets.stream().filter(v->symbol.equals(v.getSymbol())).findFirst().orElseThrow();var row=outcome(signal,bars.getFirst(),bars.getLast(),m);row.setBenchmarkReturnPct(BigDecimal.valueOf(b));rows.add(row);}signalsByDay.put(day,signals);rowsByDay.put(day,rows);marketsByDay.put(day,markets);if(TRAIN.contains(day))training.addAll(rows);}
            validateTraining(training,population);String frozenTraining=objectHash(training);var macro=new ArrayList<StockMacroFeatureSnapshot>();for(var n:input.path("macro"))macro.add(json.treeToValue(n,StockMacroFeatureSnapshot.class));var oof=new ArrayList<StockExpectedReturnSnapshot>();var oofAudit=new ArrayList<Object>();for(var day:TRAIN){var eligible=training.stream().filter(r->mature(r,day)).toList();var predictions=models(day,rowsByDay.get(day),eligible,oof,benchmark,macro,marketsByDay.get(day),population.size(),false);oof.addAll(predictions);oofAudit.add(Map.of("decision",day,"matureTrainingRows",eligible.size(),"predictions",predictions.size()));}
            var outputs=new ArrayList<Object>();var predictionsAll=new ArrayList<StockExpectedReturnSnapshot>();for(var day:TEST){var targets=rowsByDay.get(day);var predictions=models(day,targets,training,oof,benchmark,macro,marketsByDay.get(day),population.size(),true);var altered=new ArrayList<StockBacktestResult>();for(var r:targets){var c=json.convertValue(r,StockBacktestResult.class);c.setForwardReturnPct(BigDecimal.valueOf(-95));c.setBenchmarkReturnPct(BigDecimal.valueOf(80));altered.add(c);}var perturbed=models(day,altered,training,oof,benchmark,macro,marketsByDay.get(day),population.size(),true);require(normalized(predictions).equals(normalized(perturbed)),"Future target label leak "+day);var pairs=new ArrayList<Object>();for(var r:targets){var p=predictions.stream().filter(v->V9.equals(v.getModelVersion())&&r.getSymbol().equals(v.getSymbol())).findFirst().orElseThrow();var pair=new LinkedHashMap<String,Object>();pair.put("symbol",r.getSymbol());pair.put("entry",r.getEntryTradeDate());pair.put("exit",r.getExitTradeDate());pair.put("entryClose",r.getEntryClose());pair.put("exitClose",r.getExitClose());pair.put("actual",r.getForwardReturnPct());pair.put("benchmark",r.getBenchmarkReturnPct());pair.put("baselineAbsolute",p.getExpectedReturnPct());pair.put("baselineExcess",p.getExpectedExcessReturnPct());pairs.add(pair);}var counts=new TreeMap<String,Integer>();for(var p:predictions)counts.merge(p.getModelVersion(),1,Integer::sum);outputs.add(Map.of("decision",day,"newSignals",signalsByDay.get(day),"pairs",pairs,"modelCounts",counts,"futureLabelsInvariant",true));predictionsAll.addAll(predictions);}
            require(frozenTraining.equals(objectHash(training)),"Training mutated");
            var after=databaseState(db);require(before.equals(after),"Database state drift");
            for(var e:hashes.entrySet())require(sha(Path.of(e.getKey())).equals(e.getValue()),"Input changed "+e.getKey());
            Files.createDirectories(out);var report=new LinkedHashMap<String,Object>();
            report.put("classification","STRICT_UNUSED_MAR_APR_2021_DOW30_RECONSTRUCTED_RESEARCH_NOT_PROSPECTIVE");
