            report.put("financialReads",financialReads);report.put("marketReads",marketReads);report.put("sourceDatabaseBefore",before);report.put("sourceDatabaseAfter",after);
            report.put("databaseWrites",0);report.put("promotionAllowed",false);report.put("inputHashes",hashes);
